/** Stage-three immediate release, notification, resource overview and safe exports. */
final class PhaseThreeService {
  private static final int EXPORT_MAX_ROWS=5000;
  private final Path dbFile;
  PhaseThreeService(Path file){dbFile=file;}

  Map<String,Object> release(long assignmentId,long actor,String reason,String requestId)throws Exception{return release(assignmentId,actor,reason,requestId,false);}
  Map<String,Object> forceRelease(long assignmentId,long actor,String reason,String requestId)throws Exception{return release(assignmentId,actor,reason,requestId,true);}
  private Map<String,Object> release(long assignmentId,long actor,String reason,String requestId,boolean forced)throws Exception{
    if(forced&&blank(reason)==null)throw new PhaseTwoService.Problem(400,"FORCE_RELEASE_REASON_REQUIRED","管理员强制释放必须填写原因。");
    synchronized(PhaseTwoService.WRITE_LOCK){try(Connection c=open()){c.setAutoCommit(false);try{
      Map<String,Object> a=one(c,"SELECT d.id,d.status,d.version,d.switch_port AS switchPort,d.mac_address AS macAddress,d.application_id AS applicationId,d.assignment_source AS assignmentSource,d.manual_asset_type AS manualAssetType,d.manual_asset_name AS manualAssetName,d.manual_asset_code AS manualAssetCode,d.manual_user_name AS manualUserName,d.manual_user_unified_auth_id AS manualUserUnifiedAuthId,d.manual_registered_by AS registeredBy,d.manual_registered_at AS registeredAt,d.responsible_tech_user_id AS responsibleTechUserId,d.manual_note AS manualNote,d.source_pool_state AS sourcePoolState,p.ip_address AS ipAddress,COALESCE(x.applicant_user_id,d.responsible_tech_user_id) AS ownerId,COALESCE(x.asset_code,d.manual_asset_code) AS resourceCode,COALESCE(x.asset_type,d.manual_asset_type) AS assetType,b.name AS branchName,COALESCE(o.name,'') AS outletName,registered.username AS registeredByUsername,responsible.username AS responsibleTechUsername FROM ip_assignment d JOIN ip_address_pool p ON p.id=d.ip_pool_id JOIN ip_range r ON r.id=p.ip_range_id JOIN branch b ON b.id=r.branch_id LEFT JOIN outlet o ON o.id=r.outlet_id LEFT JOIN ip_application x ON x.id=d.application_id LEFT JOIN sys_user registered ON registered.id=d.manual_registered_by LEFT JOIN sys_user responsible ON responsible.id=d.responsible_tech_user_id WHERE d.id=?",assignmentId);
      if(a==null)throw new PhaseTwoService.Problem(404,"ASSIGNMENT_NOT_FOUND","IP 分配记录不存在。");
      if(!forced&&(a.get("ownerId")==null||((Number)a.get("ownerId")).longValue()!=actor))throw new PhaseTwoService.Problem(403,"RELEASE_FORBIDDEN","只能释放本人负责的有效 IP。");
      if(!"ASSIGNED".equals(a.get("status")))throw new PhaseTwoService.Problem(409,"IP_ALREADY_RELEASED","该 IP 已释放。");
      String now=Instant.now().toString();
      try(PreparedStatement p=c.prepareStatement("UPDATE ip_assignment SET status='RELEASED',released_by=?,released_at=?,release_reason=?,version=version+1 WHERE id=? AND status='ASSIGNED' AND version=?")){
        p.setLong(1,actor);p.setString(2,now);p.setString(3,blank(reason));p.setLong(4,assignmentId);p.setLong(5,((Number)a.get("version")).longValue());
        if(p.executeUpdate()!=1)throw new PhaseTwoService.Problem(409,"IP_ALREADY_RELEASED","该 IP 已释放。");
      }
      String releaser=String.valueOf(one(c,"SELECT username FROM sys_user WHERE id=?",actor).get("username"));long event;try(PreparedStatement p=c.prepareStatement("INSERT INTO ip_release_event(assignment_id,application_id,ip_address,resource_code,switch_port,mac_address,released_by,released_by_username,released_at,branch_name,outlet_name,asset_type,result,request_id,assignment_source,registered_by,registered_by_username,registered_at,responsible_tech_user_id,responsible_tech_username,manual_note,source_pool_state) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){
        p.setLong(1,assignmentId);if(a.get("applicationId")==null)p.setNull(2,Types.INTEGER);else p.setLong(2,((Number)a.get("applicationId")).longValue());p.setString(3,String.valueOf(a.get("ipAddress")));p.setString(4,(String)a.get("resourceCode"));p.setString(5,(String)a.get("switchPort"));p.setString(6,(String)a.get("macAddress"));p.setLong(7,actor);p.setString(8,releaser);p.setString(9,now);p.setString(10,String.valueOf(a.get("branchName")));p.setString(11,String.valueOf(a.get("outletName")));p.setString(12,String.valueOf(a.get("assetType")));p.setString(13,"RELEASED");p.setString(14,requestId);p.setString(15,String.valueOf(a.get("assignmentSource")));if(a.get("registeredBy")==null)p.setNull(16,Types.INTEGER);else p.setLong(16,((Number)a.get("registeredBy")).longValue());p.setString(17,(String)a.get("registeredByUsername"));p.setString(18,(String)a.get("registeredAt"));if(a.get("responsibleTechUserId")==null)p.setNull(19,Types.INTEGER);else p.setLong(19,((Number)a.get("responsibleTechUserId")).longValue());p.setString(20,(String)a.get("responsibleTechUsername"));p.setString(21,(String)a.get("manualNote"));p.setString(22,(String)a.get("sourcePoolState"));p.executeUpdate();ResultSet k=p.getGeneratedKeys();k.next();event=k.getLong(1);
      }
      String message=(forced?"管理员 ":"科技管理员 ")+releaser+" 已释放 IP "+a.get("ipAddress")+"（"+a.get("branchName")+" / "+a.get("outletName")+"），可在释放记录查看。";
      try(PreparedStatement p=c.prepareStatement("INSERT INTO user_notification(user_id,application_id,message,release_event_id) SELECT id,?,?,? FROM sys_user WHERE role='ADMIN' AND is_active=1 AND deleted_at IS NULL")){
        if(a.get("applicationId")==null)p.setNull(1,Types.INTEGER);else p.setLong(1,((Number)a.get("applicationId")).longValue());p.setString(2,message);p.setLong(3,event);p.executeUpdate();
      }
      audit(c,actor,forced?"ADMIN_FORCE_RELEASE_IP":"RELEASE_IP","IP_ASSIGNMENT",String.valueOf(assignmentId),"SUCCESS","{\"releaseEventId\":"+event+",\"assignmentSource\":\""+a.get("assignmentSource")+"\"}");c.commit();return map("id",assignmentId,"status","RELEASED","releasedAt",now,"releaseEventId",event);
    }catch(Exception e){c.rollback();throw e;}}}}
  List<Map<String,Object>> myAssignments(long actor)throws Exception{return list("SELECT d.id,d.status,d.assigned_at AS assignedAt,d.released_at AS releasedAt,d.release_reason AS releaseReason,p.ip_address AS ipAddress,r.subnet_mask AS subnetMask,r.gateway,r.dns_primary AS dnsPrimary,r.dns_secondary AS dnsSecondary,b.name AS branchName,o.name AS outletName,'APPLICATION' AS assignmentSource,x.asset_type AS assetType,x.asset_name AS assetName,x.asset_code AS assetCode,x.user_name AS userName,x.user_unified_auth_id AS userUnifiedAuthId,x.requires_user AS requiresUser,x.requires_resource_code AS requiresResourceCode FROM ip_assignment d JOIN ip_application x ON x.id=d.application_id JOIN ip_address_pool p ON p.id=d.ip_pool_id JOIN ip_range r ON r.id=p.ip_range_id JOIN branch b ON b.id=r.branch_id JOIN outlet o ON o.id=r.outlet_id WHERE d.status='ASSIGNED' AND x.applicant_user_id=? UNION ALL SELECT d.id,d.status,d.assigned_at AS assignedAt,d.released_at AS releasedAt,d.release_reason AS releaseReason,p.ip_address AS ipAddress,r.subnet_mask AS subnetMask,r.gateway,r.dns_primary AS dnsPrimary,r.dns_secondary AS dnsSecondary,b.name AS branchName,o.name AS outletName,'MANUAL_REGISTRATION' AS assignmentSource,d.manual_asset_type AS assetType,d.manual_asset_name AS assetName,d.manual_asset_code AS assetCode,d.manual_user_name AS userName,d.manual_user_unified_auth_id AS userUnifiedAuthId,d.manual_requires_user AS requiresUser,d.manual_requires_resource_code AS requiresResourceCode FROM ip_assignment d JOIN ip_address_pool p ON p.id=d.ip_pool_id JOIN ip_range r ON r.id=p.ip_range_id JOIN branch b ON b.id=r.branch_id LEFT JOIN outlet o ON o.id=r.outlet_id WHERE d.status='ASSIGNED' AND d.assignment_source='MANUAL_REGISTRATION' AND d.responsible_tech_user_id=? ORDER BY 1 DESC",actor,actor);}
  List<Map<String,Object>> notifications(long actor)throws Exception{return list("SELECT n.id,n.message,n.is_read AS isRead,n.created_at AS createdAt,n.release_event_id AS releaseEventId FROM user_notification n WHERE n.user_id=? ORDER BY n.id DESC LIMIT 200",actor);}
  void markRead(long id,long actor)throws Exception{synchronized(PhaseTwoService.WRITE_LOCK){try(Connection c=open();PreparedStatement p=c.prepareStatement("UPDATE user_notification SET is_read=1 WHERE id=? AND user_id=?")){p.setLong(1,id);p.setLong(2,actor);if(p.executeUpdate()!=1)throw new PhaseTwoService.Problem(404,"NOTIFICATION_NOT_FOUND","通知不存在。");}}}

  List<Map<String,Object>> releases(String q,String branch,String outlet,String asset,String from,String to)throws Exception{
    StringBuilder sql=new StringBuilder("SELECT e.id,e.ip_address AS ipAddress,e.resource_code AS resourceCode,e.switch_port AS switchPort,e.mac_address AS macAddress,e.released_by_username AS releasedBy,e.released_at AS releasedAt,e.branch_name AS branchName,e.outlet_name AS outletName,e.asset_type AS assetType,e.assignment_id AS assignmentId,e.assignment_source AS assignmentSource,e.registered_by_username AS registeredBy,e.registered_at AS registeredAt,e.responsible_tech_username AS responsibleTech,e.manual_note AS manualNote,e.source_pool_state AS sourcePoolState,a.action AS auditAction FROM ip_release_event e LEFT JOIN audit_log a ON a.target_type='IP_ASSIGNMENT' AND a.target_id=CAST(e.assignment_id AS TEXT) AND a.action IN ('RELEASE_IP','ADMIN_FORCE_RELEASE_IP') WHERE 1=1");List<Object> args=new ArrayList<>();addLike(sql,args,"e.released_by_username",q);addLike(sql,args,"e.ip_address",q);addEq(sql,args,"e.branch_name",branch);addEq(sql,args,"e.outlet_name",outlet);addEq(sql,args,"e.asset_type",asset);addFrom(sql,args,"e.released_at",from);addTo(sql,args,"e.released_at",to);sql.append(" GROUP BY e.id ORDER BY e.id DESC LIMIT 1000");return list(sql.toString(),args.toArray());
  }
  Map<String,Object> reachability(long poolId)throws Exception{Map<String,Object> item;try(Connection c=open()){item=one(c,"SELECT p.ip_address AS ipAddress FROM ip_address_pool p JOIN ip_range r ON r.id=p.ip_range_id LEFT JOIN ip_assignment a ON a.ip_pool_id=p.id AND a.status='ASSIGNED' WHERE p.id=? AND p.is_active=1 AND p.is_reserved=0 AND p.deleted_at IS NULL AND r.deleted_at IS NULL AND a.id IS NULL",poolId);}if(item==null)throw new PhaseTwoService.Problem(409,"IP_NOT_AVAILABLE","该 IP 已不可用，无法执行连通性检测。");String ip=String.valueOf(item.get("ipAddress"));long start=System.currentTimeMillis();try{boolean reachable=InetAddress.getByName(ip).isReachable(1200);return map("ipAddress",ip,"status",reachable?"REACHABLE":"NO_REPLY","elapsedMs",System.currentTimeMillis()-start);}catch(Exception e){return map("ipAddress",ip,"status","CHECK_FAILED","elapsedMs",System.currentTimeMillis()-start);}}
  Map<String,Object> overview(String branch,String outlet)throws Exception{
    String where=" WHERE p.deleted_at IS NULL AND r.deleted_at IS NULL AND b.deleted_at IS NULL AND o.deleted_at IS NULL";List<Object> args=new ArrayList<>();if(!empty(branch)){where+=" AND b.id=?";args.add(Long.valueOf(branch));}if(!empty(outlet)){where+=" AND o.id=?";args.add(Long.valueOf(outlet));}
    String sql="SELECT count(*) AS addressTotal,sum(CASE WHEN p.is_active=1 AND p.is_reserved=0 AND a.id IS NULL THEN 1 ELSE 0 END) AS availableCount,sum(CASE WHEN a.id IS NOT NULL THEN 1 ELSE 0 END) AS assignedCount,sum(CASE WHEN p.is_active=0 AND p.ip_address<>r.gateway AND a.id IS NULL THEN 1 ELSE 0 END) AS disabledCount,sum(CASE WHEN p.is_active=1 AND p.is_reserved=1 AND p.ip_address<>r.gateway AND a.id IS NULL THEN 1 ELSE 0 END) AS manualReservedCount,sum(CASE WHEN p.ip_address=r.gateway AND a.id IS NULL THEN 1 ELSE 0 END) AS systemReservedCount FROM ip_address_pool p JOIN ip_range r ON r.id=p.ip_range_id JOIN outlet o ON o.id=r.outlet_id JOIN branch b ON b.id=o.branch_id LEFT JOIN ip_assignment a ON a.ip_pool_id=p.id AND a.status='ASSIGNED'"+where;
    Map<String,Object> m;try(Connection c=open()){m=one(c,sql,args.toArray());}if(m==null)m=new LinkedHashMap<>();for(String k:Arrays.asList("addressTotal","availableCount","assignedCount","disabledCount","manualReservedCount","systemReservedCount"))if(m.get(k)==null)m.put(k,0L);
    long released=count("SELECT count(*) FROM ip_release_event",new Object[0]),today=count("SELECT count(*) FROM ip_release_event WHERE substr(released_at,1,10)=?",new Object[]{LocalDate.now(ZoneOffset.UTC).toString()}),pending=count("SELECT count(*) FROM ip_application WHERE status='PENDING'",new Object[0]);m.put("releasedTotal",released);m.put("todayReleased",today);m.put("pendingCount",pending);long available=((Number)m.get("availableCount")).longValue(),assigned=((Number)m.get("assignedCount")).longValue(),capacity=available+assigned;m.put("allocatableCapacity",capacity);m.put("usageRate",capacity==0?0D:Math.round(assigned*10000D/capacity)/100D);
    m.put("branches",list("SELECT b.id,b.name AS branchName,sum(CASE WHEN p.is_active=1 AND p.is_reserved=0 AND a.id IS NULL THEN 1 ELSE 0 END) AS availableCount,sum(CASE WHEN a.id IS NOT NULL THEN 1 ELSE 0 END) AS assignedCount FROM branch b JOIN outlet o ON o.branch_id=b.id JOIN ip_range r ON r.outlet_id=o.id JOIN ip_address_pool p ON p.ip_range_id=r.id LEFT JOIN ip_assignment a ON a.ip_pool_id=p.id AND a.status='ASSIGNED' WHERE b.deleted_at IS NULL AND o.deleted_at IS NULL AND r.deleted_at IS NULL AND p.deleted_at IS NULL GROUP BY b.id ORDER BY b.name"));
    m.put("outlets",list("SELECT o.id,b.name AS branchName,o.name AS outletName,sum(CASE WHEN p.is_active=1 AND p.is_reserved=0 AND a.id IS NULL THEN 1 ELSE 0 END) AS availableCount FROM outlet o JOIN branch b ON b.id=o.branch_id LEFT JOIN ip_range r ON r.outlet_id=o.id AND r.deleted_at IS NULL LEFT JOIN ip_address_pool p ON p.ip_range_id=r.id AND p.deleted_at IS NULL LEFT JOIN ip_assignment a ON a.ip_pool_id=p.id AND a.status='ASSIGNED' WHERE b.deleted_at IS NULL AND o.deleted_at IS NULL GROUP BY o.id ORDER BY b.name,o.name"));return m;
  }
  Map<String,Object> overview(String branch,String outlet,int branchPage,int outletPage)throws Exception{
    Map<String,Object> m=overview(branch,outlet);int bp=Math.max(1,branchPage),op=Math.max(1,outletPage),size=20;
    List<Map<String,Object>> branches=(List<Map<String,Object>>)m.get("branches"),outlets=(List<Map<String,Object>>)m.get("outlets");
    m.put("branchTotal",Long.valueOf(branches.size()));m.put("outletTotal",Long.valueOf(outlets.size()));m.put("branchPage",Integer.valueOf(bp));m.put("outletPage",Integer.valueOf(op));m.put("pageSize",Integer.valueOf(size));
    m.put("branches",slice(branches,bp,size));m.put("outlets",slice(outlets,op,size));return m;
  }
  private static List<Map<String,Object>> slice(List<Map<String,Object>> rows,int page,int size){int from=Math.min(rows.size(),(page-1)*size),to=Math.min(rows.size(),from+size);return new ArrayList<Map<String,Object>>(rows.subList(from,to));}
  byte[] export(String type,String format,Set<String> fields,Map<String,String> filters,long actor)throws Exception{String kind=type==null?"":type.toUpperCase(Locale.ROOT);Map<String,String> sqls=new HashMap<>();String common="x.asset_type AS assetType,x.asset_name AS assetName,x.asset_code AS resourceCode,x.user_name AS userName,x.user_unified_auth_id AS userUnifiedAuthId,x.applicant_username AS applicantUsername,x.applicant_name AS applicantName,x.created_at AS applicationCreatedAt,x.status,x.recommended_range_type AS recommendedRangeType,x.final_range_type AS finalRangeType,x.override_reason AS overrideReason,reviewer.username AS reviewer,x.reviewed_at AS reviewedAt";sqls.put("POOL","SELECT p.ip_address AS ipAddress,b.name AS branchName,o.name AS outletName,r.range_type AS rangeType,r.cidr,CASE WHEN a.id IS NOT NULL THEN 'ASSIGNED' WHEN p.ip_address=r.gateway THEN 'SYSTEM_RESERVED' WHEN p.is_reserved=1 THEN 'MANUAL_RESERVED' WHEN p.is_active=1 THEN 'AVAILABLE' ELSE 'DISABLED' END AS state,a.switch_port AS switchPort,"+common+",a.assigned_at AS assignedAt,a.released_at AS releasedAt,a.release_reason AS releaseReason,releaser.username AS releasedBy FROM ip_address_pool p JOIN ip_range r ON r.id=p.ip_range_id JOIN outlet o ON o.id=r.outlet_id JOIN branch b ON b.id=o.branch_id LEFT JOIN ip_assignment a ON a.ip_pool_id=p.id AND a.status='ASSIGNED' LEFT JOIN ip_application x ON x.id=a.application_id LEFT JOIN sys_user reviewer ON reviewer.id=x.reviewed_by LEFT JOIN sys_user releaser ON releaser.id=a.released_by WHERE p.deleted_at IS NULL AND r.deleted_at IS NULL ORDER BY p.id");sqls.put("APPLICATION","SELECT b.name AS branchName,o.name AS outletName,r.range_type AS rangeType,r.cidr,p.ip_address AS ipAddress,d.switch_port AS switchPort,"+common+" FROM ip_application x JOIN branch b ON b.id=x.branch_id JOIN outlet o ON o.id=x.outlet_id LEFT JOIN sys_user reviewer ON reviewer.id=x.reviewed_by LEFT JOIN ip_assignment d ON d.application_id=x.id LEFT JOIN ip_address_pool p ON p.id=d.ip_pool_id LEFT JOIN ip_range r ON r.id=p.ip_range_id ORDER BY x.id");sqls.put("ASSIGNMENT","SELECT p.ip_address AS ipAddress,b.name AS branchName,o.name AS outletName,r.range_type AS rangeType,r.cidr,d.switch_port AS switchPort,"+common+",d.assigned_at AS assignedAt,releaser.username AS releasedBy,d.released_at AS releasedAt,d.release_reason AS releaseReason,d.status FROM ip_assignment d JOIN ip_application x ON x.id=d.application_id JOIN ip_address_pool p ON p.id=d.ip_pool_id JOIN ip_range r ON r.id=p.ip_range_id JOIN outlet o ON o.id=r.outlet_id JOIN branch b ON b.id=o.branch_id LEFT JOIN sys_user reviewer ON reviewer.id=x.reviewed_by LEFT JOIN sys_user releaser ON releaser.id=d.released_by ORDER BY d.id");sqls.put("RELEASE","SELECT e.ip_address AS ipAddress,e.resource_code AS resourceCode,e.switch_port AS switchPort,e.released_by_username AS releasedBy,e.released_at AS releasedAt,e.branch_name AS branchName,e.outlet_name AS outletName,e.asset_type AS assetType FROM ip_release_event e ORDER BY e.id");sqls.put("STATISTICS","SELECT b.name AS branchName,o.name AS outletName,sum(CASE WHEN p.is_active=1 AND p.is_reserved=0 AND a.id IS NULL THEN 1 ELSE 0 END) AS availableCount,sum(CASE WHEN a.id IS NOT NULL THEN 1 ELSE 0 END) AS assignedCount FROM branch b JOIN outlet o ON o.branch_id=b.id LEFT JOIN ip_range r ON r.outlet_id=o.id LEFT JOIN ip_address_pool p ON p.ip_range_id=r.id LEFT JOIN ip_assignment a ON a.ip_pool_id=p.id AND a.status='ASSIGNED' WHERE b.deleted_at IS NULL AND o.deleted_at IS NULL GROUP BY b.id,o.id ORDER BY b.name,o.name");if(!sqls.containsKey(kind))throw new PhaseTwoService.Problem(400,"EXPORT_TYPE_INVALID","导出类型不正确。");List<Map<String,Object>> rows=list(sqls.get(kind));if(rows.size()>EXPORT_MAX_ROWS)throw new PhaseTwoService.Problem(409,"EXPORT_TOO_LARGE","导出数据超过最大行数，请缩小范围。");List<String> allowed=allowedV017(kind),selected=new ArrayList<String>();for(String f:allowed)if(fields==null||fields.isEmpty()||fields.contains(f))selected.add(f);if(selected.isEmpty())throw new PhaseTwoService.Problem(400,"EXPORT_FIELDS_INVALID","至少选择一个允许导出的字段。");try(Connection c=open()){audit(c,actor,"EXPORT_"+kind,"EXPORT",kind,"SUCCESS","{\"rows\":"+rows.size()+",\"fields\":\""+String.join(",",selected)+"\"}");}return "XLSX".equalsIgnoreCase(format)?xlsx(selected,rows):csv(selected,rows);}
  private static List<String> allowedV017(String kind){List<String> all=Arrays.asList("branchName","outletName","rangeType","cidr","ipAddress","state","switchPort","assetType","assetName","resourceCode","userName","userUnifiedAuthId","applicantUsername","applicantName","applicationCreatedAt","status","recommendedRangeType","finalRangeType","overrideReason","reviewer","reviewedAt","assignedAt","releasedBy","releasedAt","releaseReason");if("RELEASE".equals(kind))return Arrays.asList("ipAddress","resourceCode","switchPort","releasedBy","releasedAt","branchName","outletName","assetType");if("STATISTICS".equals(kind))return Arrays.asList("branchName","outletName","availableCount","assignedCount");return all;}
  private static List<String> allowedManual(String kind){List<String> all=Arrays.asList("branchName","outletName","rangeType","cidr","ipAddress","state","switchPort","macAddress","assetType","assetName","resourceCode","userName","userUnifiedAuthId","applicantUsername","applicantName","applicationCreatedAt","assignmentSource","registeredBy","registeredAt","responsibleTech","manualNote","sourcePoolState","status","recommendedRangeType","finalRangeType","overrideReason","reviewer","reviewedAt","assignedAt","releasedBy","releasedAt","releaseReason");if("RELEASE".equals(kind))return Arrays.asList("ipAddress","resourceCode","switchPort","macAddress","releasedBy","releasedAt","branchName","outletName","assetType","assignmentSource","registeredBy","registeredAt","responsibleTech","manualNote","sourcePoolState");if("STATISTICS".equals(kind))return Arrays.asList("branchName","outletName","availableCount","assignedCount");return all;}
  private static Set<String> manualExportKinds(){return new HashSet<String>(Arrays.asList("POOL","APPLICATION","ASSIGNMENT","RELEASE","STATISTICS"));}
  private String manualExportSql(String kind){
    String allocation="COALESCE(x.asset_type,d.manual_asset_type) AS assetType,COALESCE(x.asset_name,d.manual_asset_name) AS assetName,COALESCE(x.asset_code,d.manual_asset_code) AS resourceCode,COALESCE(x.user_name,d.manual_user_name) AS userName,COALESCE(x.user_unified_auth_id,d.manual_user_unified_auth_id) AS userUnifiedAuthId,x.applicant_username AS applicantUsername,x.applicant_name AS applicantName,x.created_at AS applicationCreatedAt,COALESCE(d.assignment_source,'APPLICATION') AS assignmentSource,registrar.username AS registeredBy,d.manual_registered_at AS registeredAt,responsible.username AS responsibleTech,d.manual_note AS manualNote,d.source_pool_state AS sourcePoolState,x.status,x.recommended_range_type AS recommendedRangeType,x.final_range_type AS finalRangeType,x.override_reason AS overrideReason,reviewer.username AS reviewer,x.reviewed_at AS reviewedAt";
    if("POOL".equals(kind))return "SELECT p.ip_address AS ipAddress,b.name AS branchName,o.name AS outletName,r.range_type AS rangeType,r.cidr,CASE WHEN d.id IS NOT NULL THEN 'ASSIGNED' WHEN p.ip_address=r.gateway THEN 'SYSTEM_RESERVED' WHEN p.is_reserved=1 THEN 'MANUAL_RESERVED' WHEN p.is_active=1 THEN 'AVAILABLE' ELSE 'DISABLED' END AS state,d.switch_port AS switchPort,d.mac_address AS macAddress,"+allocation+",d.assigned_at AS assignedAt,d.released_at AS releasedAt,d.release_reason AS releaseReason,releaser.username AS releasedBy FROM ip_address_pool p JOIN ip_range r ON r.id=p.ip_range_id JOIN outlet o ON o.id=r.outlet_id JOIN branch b ON b.id=o.branch_id LEFT JOIN ip_assignment d ON d.ip_pool_id=p.id AND d.status='ASSIGNED' LEFT JOIN ip_application x ON x.id=d.application_id LEFT JOIN sys_user reviewer ON reviewer.id=x.reviewed_by LEFT JOIN sys_user registrar ON registrar.id=d.manual_registered_by LEFT JOIN sys_user responsible ON responsible.id=d.responsible_tech_user_id LEFT JOIN sys_user releaser ON releaser.id=d.released_by WHERE p.deleted_at IS NULL AND r.deleted_at IS NULL ORDER BY p.id";
    if("APPLICATION".equals(kind))return "SELECT b.name AS branchName,o.name AS outletName,r.range_type AS rangeType,r.cidr,p.ip_address AS ipAddress,d.switch_port AS switchPort,d.mac_address AS macAddress,"+allocation+" FROM ip_application x JOIN branch b ON b.id=x.branch_id JOIN outlet o ON o.id=x.outlet_id LEFT JOIN sys_user reviewer ON reviewer.id=x.reviewed_by LEFT JOIN ip_assignment d ON d.application_id=x.id LEFT JOIN ip_address_pool p ON p.id=d.ip_pool_id LEFT JOIN ip_range r ON r.id=p.ip_range_id LEFT JOIN sys_user registrar ON registrar.id=d.manual_registered_by LEFT JOIN sys_user responsible ON responsible.id=d.responsible_tech_user_id ORDER BY x.id";
    if("ASSIGNMENT".equals(kind))return "SELECT p.ip_address AS ipAddress,b.name AS branchName,o.name AS outletName,r.range_type AS rangeType,r.cidr,d.switch_port AS switchPort,d.mac_address AS macAddress,"+allocation+",d.assigned_at AS assignedAt,releaser.username AS releasedBy,d.released_at AS releasedAt,d.release_reason AS releaseReason,d.status FROM ip_assignment d JOIN ip_address_pool p ON p.id=d.ip_pool_id JOIN ip_range r ON r.id=p.ip_range_id JOIN outlet o ON o.id=r.outlet_id JOIN branch b ON b.id=r.branch_id LEFT JOIN ip_application x ON x.id=d.application_id LEFT JOIN sys_user reviewer ON reviewer.id=x.reviewed_by LEFT JOIN sys_user registrar ON registrar.id=d.manual_registered_by LEFT JOIN sys_user responsible ON responsible.id=d.responsible_tech_user_id LEFT JOIN sys_user releaser ON releaser.id=d.released_by ORDER BY d.id";
    if("RELEASE".equals(kind))return "SELECT e.ip_address AS ipAddress,e.resource_code AS resourceCode,e.switch_port AS switchPort,e.mac_address AS macAddress,e.released_by_username AS releasedBy,e.released_at AS releasedAt,e.branch_name AS branchName,e.outlet_name AS outletName,e.asset_type AS assetType,e.assignment_source AS assignmentSource,e.registered_by_username AS registeredBy,e.registered_at AS registeredAt,e.responsible_tech_username AS responsibleTech,e.manual_note AS manualNote,e.source_pool_state AS sourcePoolState FROM ip_release_event e ORDER BY e.id";
    return "SELECT b.name AS branchName,o.name AS outletName,sum(CASE WHEN p.is_active=1 AND p.is_reserved=0 AND d.id IS NULL THEN 1 ELSE 0 END) AS availableCount,sum(CASE WHEN d.id IS NOT NULL THEN 1 ELSE 0 END) AS assignedCount FROM branch b JOIN outlet o ON o.branch_id=b.id LEFT JOIN ip_range r ON r.outlet_id=o.id LEFT JOIN ip_address_pool p ON p.ip_range_id=r.id LEFT JOIN ip_assignment d ON d.ip_pool_id=p.id AND d.status='ASSIGNED' WHERE b.deleted_at IS NULL AND o.deleted_at IS NULL GROUP BY b.id,o.id ORDER BY b.name,o.name";
  }
  byte[] exportManualAware(String type,String format,Set<String> fields,Map<String,String> filters,long actor)throws Exception{
    String kind=type==null?"":type.toUpperCase(Locale.ROOT);if(!manualExportKinds().contains(kind))throw new PhaseTwoService.Problem(400,"EXPORT_TYPE_INVALID","导出类型不正确。");
    List<Map<String,Object>> rows=list(manualExportSql(kind));if(rows.size()>EXPORT_MAX_ROWS)throw new PhaseTwoService.Problem(409,"EXPORT_TOO_LARGE","导出数据超过最大行数，请缩小范围。");
    List<String> allowed=allowedManual(kind),selected=new ArrayList<String>();for(String f:allowed)if(fields==null||fields.isEmpty()||fields.contains(f))selected.add(f);if(selected.isEmpty())throw new PhaseTwoService.Problem(400,"EXPORT_FIELDS_INVALID","至少选择一个允许导出的字段。");
    try(Connection c=open()){audit(c,actor,"EXPORT_"+kind,"EXPORT",kind,"SUCCESS",null);}return "XLSX".equalsIgnoreCase(format)?xlsx(selected,rows):csv(selected,rows);
  }
  byte[] exportLegacy(String type,String format,Set<String> fields,Map<String,String> filters,long actor)throws Exception{
    String kind=type==null?"":type.toUpperCase(Locale.ROOT);Map<String,String> sqls=new HashMap<>();sqls.put("POOL","SELECT p.ip_address AS ipAddress,b.name AS branchName,o.name AS outletName,r.range_type AS rangeType,r.cidr,CASE WHEN a.id IS NOT NULL THEN 'ASSIGNED' WHEN p.ip_address=r.gateway THEN 'SYSTEM_RESERVED' WHEN p.is_reserved=1 THEN 'MANUAL_RESERVED' WHEN p.is_active=1 THEN 'AVAILABLE' ELSE 'DISABLED' END AS state,c.name AS category,s.name AS subcategory,CASE WHEN x.asset_type='TECH' AND x.device_type='OTHER' THEN x.asset_code END AS resourceCode,CASE WHEN x.asset_type='TECH' AND x.device_type='PC' THEN x.user_name END AS userName,CASE WHEN x.asset_type='TECH' AND x.device_type='PC' THEN x.user_unified_auth_id END AS userUnifiedAuthId,x.applicant_username AS applicantUsername,x.applicant_name AS applicantName,x.created_at AS applicationCreatedAt,x.status,x.recommended_range_type AS recommendedRangeType,x.final_range_type AS finalRangeType,reviewer.username AS reviewer,x.reviewed_at AS reviewedAt,a.assigned_at AS assignedAt,a.released_at AS releasedAt,a.release_reason AS releaseReason,releaser.username AS releasedBy FROM ip_address_pool p JOIN ip_range r ON r.id=p.ip_range_id JOIN outlet o ON o.id=r.outlet_id JOIN branch b ON b.id=o.branch_id LEFT JOIN ip_assignment a ON a.ip_pool_id=p.id AND a.status='ASSIGNED' LEFT JOIN ip_application x ON x.id=a.application_id LEFT JOIN asset_subcategory s ON s.id=x.subcategory_id LEFT JOIN asset_category c ON c.id=s.category_id LEFT JOIN sys_user reviewer ON reviewer.id=x.reviewed_by LEFT JOIN sys_user releaser ON releaser.id=a.released_by WHERE p.deleted_at IS NULL AND r.deleted_at IS NULL ORDER BY p.id");sqls.put("APPLICATION","SELECT x.id,x.applicant_username AS applicantUsername,x.applicant_name AS applicantName,b.name AS branchName,o.name AS outletName,r.range_type AS rangeType,c.name AS category,s.name AS subcategory,CASE WHEN x.asset_type='TECH' AND x.device_type='OTHER' THEN x.asset_code END AS resourceCode,CASE WHEN x.asset_type='TECH' AND x.device_type='PC' THEN x.user_name END AS userName,CASE WHEN x.asset_type='TECH' AND x.device_type='PC' THEN x.user_unified_auth_id END AS userUnifiedAuthId,x.status,x.recommended_range_type AS recommendedRangeType,x.final_range_type AS finalRangeType,reviewer.username AS reviewer,x.reviewed_at AS reviewedAt,x.created_at AS applicationCreatedAt FROM ip_application x JOIN branch b ON b.id=x.branch_id JOIN outlet o ON o.id=x.outlet_id LEFT JOIN asset_subcategory s ON s.id=x.subcategory_id LEFT JOIN asset_category c ON c.id=s.category_id LEFT JOIN sys_user reviewer ON reviewer.id=x.reviewed_by LEFT JOIN ip_assignment d ON d.application_id=x.id LEFT JOIN ip_address_pool p ON p.id=d.ip_pool_id LEFT JOIN ip_range r ON r.id=p.ip_range_id ORDER BY x.id");sqls.put("ASSIGNMENT","SELECT p.ip_address AS ipAddress,b.name AS branchName,o.name AS outletName,r.range_type AS rangeType,r.cidr,c.name AS category,s.name AS subcategory,CASE WHEN x.asset_type='TECH' AND x.device_type='OTHER' THEN x.asset_code END AS resourceCode,CASE WHEN x.asset_type='TECH' AND x.device_type='PC' THEN x.user_name END AS userName,CASE WHEN x.asset_type='TECH' AND x.device_type='PC' THEN x.user_unified_auth_id END AS userUnifiedAuthId,x.applicant_username AS applicantUsername,x.applicant_name AS applicantName,x.created_at AS applicationCreatedAt,x.status,x.recommended_range_type AS recommendedRangeType,x.final_range_type AS finalRangeType,reviewer.username AS reviewer,x.reviewed_at AS reviewedAt,d.assigned_at AS assignedAt,releaser.username AS releasedBy,d.released_at AS releasedAt,d.release_reason AS releaseReason,d.status FROM ip_assignment d JOIN ip_application x ON x.id=d.application_id JOIN ip_address_pool p ON p.id=d.ip_pool_id JOIN ip_range r ON r.id=p.ip_range_id JOIN outlet o ON o.id=r.outlet_id JOIN branch b ON b.id=o.branch_id LEFT JOIN asset_subcategory s ON s.id=x.subcategory_id LEFT JOIN asset_category c ON c.id=s.category_id LEFT JOIN sys_user reviewer ON reviewer.id=x.reviewed_by LEFT JOIN sys_user releaser ON releaser.id=d.released_by ORDER BY d.id");sqls.put("RELEASE","SELECT e.ip_address AS ipAddress,e.resource_code AS resourceCode,e.released_by_username AS releasedBy,e.released_at AS releasedAt,e.branch_name AS branchName,e.outlet_name AS outletName,e.asset_type AS assetType FROM ip_release_event e ORDER BY e.id");sqls.put("STATISTICS","SELECT b.name AS branchName,o.name AS outletName,sum(CASE WHEN p.is_active=1 AND p.is_reserved=0 AND a.id IS NULL THEN 1 ELSE 0 END) AS availableCount,sum(CASE WHEN a.id IS NOT NULL THEN 1 ELSE 0 END) AS assignedCount FROM branch b JOIN outlet o ON o.branch_id=b.id LEFT JOIN ip_range r ON r.outlet_id=o.id LEFT JOIN ip_address_pool p ON p.ip_range_id=r.id LEFT JOIN ip_assignment a ON a.ip_pool_id=p.id AND a.status='ASSIGNED' WHERE b.deleted_at IS NULL AND o.deleted_at IS NULL GROUP BY b.id,o.id ORDER BY b.name,o.name");if(!sqls.containsKey(kind))throw new PhaseTwoService.Problem(400,"EXPORT_TYPE_INVALID","导出类型不正确。");
    List<Map<String,Object>> rows=list(sqls.get(kind));if(rows.size()>EXPORT_MAX_ROWS)throw new PhaseTwoService.Problem(409,"EXPORT_TOO_LARGE","导出数据超过最大行数，请缩小范围。");if(rows.isEmpty())rows=new ArrayList<>();List<String> allowed=allowed(kind);List<String> selected=new ArrayList<>();for(String f:allowed)if(fields==null||fields.isEmpty()||fields.contains(f))selected.add(f);if(selected.isEmpty())throw new PhaseTwoService.Problem(400,"EXPORT_FIELDS_INVALID","至少选择一个允许导出的字段。");try(Connection c=open()){audit(c,actor,"EXPORT_"+kind,"EXPORT",kind,"SUCCESS","{\"rows\":"+rows.size()+",\"fields\":\""+String.join(",",selected)+"\"}");}
    return "XLSX".equalsIgnoreCase(format)?xlsx(selected,rows):csv(selected,rows);
  }
  private static List<String> allowed(String kind){Map<String,List<String>> x=new HashMap<>();List<String> all=Arrays.asList("branchName","outletName","rangeType","cidr","ipAddress","state","category","subcategory","resourceCode","userName","userUnifiedAuthId","applicantUsername","applicantName","applicationCreatedAt","status","recommendedRangeType","finalRangeType","reviewer","reviewedAt","assignedAt","releasedBy","releasedAt","releaseReason");x.put("POOL",all);x.put("APPLICATION",all);x.put("ASSIGNMENT",all);x.put("RELEASE",Arrays.asList("ipAddress","resourceCode","releasedBy","releasedAt","branchName","outletName","assetType"));x.put("STATISTICS",Arrays.asList("branchName","outletName","availableCount","assignedCount"));return x.get(kind);}
  private static byte[] csv(List<String> fields,List<Map<String,Object>> rows)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(0xef);out.write(0xbb);out.write(0xbf);out.write(line(fields).getBytes(StandardCharsets.UTF_8));for(Map<String,Object> row:rows){List<String> values=new ArrayList<>();for(String f:fields)values.add(safe(row.get(f)));out.write(line(values).getBytes(StandardCharsets.UTF_8));}return out.toByteArray();}
  private static byte[] xlsx(List<String> fields,List<Map<String,Object>> rows)throws Exception{try(XSSFWorkbook wb=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){Sheet sheet=wb.createSheet("export");Row h=sheet.createRow(0);for(int i=0;i<fields.size();i++)h.createCell(i,CellType.STRING).setCellValue(fields.get(i));int n=1;for(Map<String,Object> row:rows){Row r=sheet.createRow(n++);for(int i=0;i<fields.size();i++)r.createCell(i,CellType.STRING).setCellValue(safe(row.get(fields.get(i))));}wb.write(out);return out.toByteArray();}}
  private static String line(List<String> v){StringBuilder b=new StringBuilder();for(int i=0;i<v.size();i++){if(i>0)b.append(',');b.append('"').append(v.get(i).replace("\"","\"\"")).append('"');}return b.append("\r\n").toString();}private static String safe(Object value){String x=value==null?"":String.valueOf(value);String trim=x.replaceFirst("^\\s+","");return trim.startsWith("=")||trim.startsWith("+")||trim.startsWith("-")||trim.startsWith("@")?"'"+x:x;}
  private Connection open()throws Exception{Connection c=DriverManager.getConnection("jdbc:sqlite:"+dbFile);try(Statement s=c.createStatement()){s.execute("PRAGMA foreign_keys=ON");s.execute("PRAGMA busy_timeout=5000");}return c;}
  private Map<String,Object> one(Connection c,String sql,Object...args)throws Exception{try(PreparedStatement p=c.prepareStatement(sql)){bind(p,args);try(ResultSet r=p.executeQuery()){return r.next()?row(r):null;}}}private List<Map<String,Object>> list(String sql,Object...args)throws Exception{try(Connection c=open()){return list(c,sql,args);}}private List<Map<String,Object>> list(Connection c,String sql,Object...args)throws Exception{try(PreparedStatement p=c.prepareStatement(sql)){bind(p,args);try(ResultSet r=p.executeQuery()){List<Map<String,Object>> out=new ArrayList<>();while(r.next())out.add(row(r));return out;}}}private static Map<String,Object> row(ResultSet r)throws Exception{Map<String,Object> m=new LinkedHashMap<>();ResultSetMetaData md=r.getMetaData();for(int i=1;i<=md.getColumnCount();i++)m.put(md.getColumnLabel(i),r.getObject(i));return m;}private long count(String sql,Object[] args)throws Exception{try(Connection c=open();PreparedStatement p=c.prepareStatement(sql)){bind(p,args);ResultSet r=p.executeQuery();r.next();return r.getLong(1);}}private static void bind(PreparedStatement p,Object...a)throws Exception{for(int i=0;i<a.length;i++){if(a[i] instanceof Long)p.setLong(i+1,(Long)a[i]);else p.setString(i+1,String.valueOf(a[i]));}}private static void audit(Connection c,long actor,String action,String type,String target,String result,String detail)throws Exception{try(PreparedStatement p=c.prepareStatement("INSERT INTO audit_log(actor_user_id,action,target_type,target_id,result,detail_json) VALUES(?,?,?,?,?,?)")){p.setLong(1,actor);p.setString(2,action);p.setString(3,type);p.setString(4,target);p.setString(5,result);p.setString(6,detail);p.executeUpdate();}}private static void addLike(StringBuilder s,List<Object>a,String f,String v){if(!empty(v)){s.append(" AND ").append(f).append(" LIKE ?");a.add("%"+v.trim()+"%");}}private static void addEq(StringBuilder s,List<Object>a,String f,String v){if(!empty(v)){s.append(" AND ").append(f).append("=?");a.add(v.trim());}}private static void addFrom(StringBuilder s,List<Object>a,String f,String v){if(!empty(v)){s.append(" AND ").append(f).append(">=?");a.add(v.trim());}}private static void addTo(StringBuilder s,List<Object>a,String f,String v){if(!empty(v)){s.append(" AND ").append(f).append("<=?");a.add(v.trim()+"T23:59:59.999Z");}}private static boolean empty(String v){return v==null||v.trim().isEmpty();}private static String blank(String v){return empty(v)?null:v.trim();}private static Map<String,Object> map(Object...v){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<v.length;i+=2)m.put(String.valueOf(v[i]),v[i+1]);return m;}
}
